require 'opentelemetry/sdk'
require 'opentelemetry/instrumentation/all'
require 'opentelemetry/exporter/otlp'

# Exports nowhere until OTEL_EXPORTER_OTLP_ENDPOINT is configured — the Ruby SDK's own default
# (no endpoint set) is NOT a no-op: it hardcodes http://localhost:4318 and retries with backoff,
# silently dropping telemetry with no log line for the common connection-refused case. Setting
# OTEL_TRACES_EXPORTER explicitly restores the same "exports nowhere until configured" guarantee
# every other language this plugin generates for already makes. Verified against
# opentelemetry-sdk 1.13.0 / opentelemetry-exporter-otlp 0.35.1 source plus a live run — do not
# remove this line or assume the SDK no-ops on its own.
ENV['OTEL_TRACES_EXPORTER'] ||= ENV['OTEL_EXPORTER_OTLP_ENDPOINT'] ? 'otlp' : 'none'

OpenTelemetry::SDK.configure do |c|
  c.service_name = ENV.fetch('OTEL_SERVICE_NAME', 'notifications-api')
  c.resource = OpenTelemetry::SDK::Resources::Resource.create({
    'service.version' => ENV.fetch('OTEL_SERVICE_VERSION', '1.1.0'),
    'service.namespace' => ENV.fetch('OTEL_SERVICE_NAMESPACE', 'storefront'),
    'deployment.environment.name' => ENV.fetch('DEPLOYMENT_ENV', 'development'),
  })
  c.use_all
end

# Trace IDs in the application's own log lines (#279). Nothing here runs unless the application
# calls it; /otel-instrument prints the one line that does. Both read the current span, so a line
# written outside a span (or while no endpoint is set, when no spans are made) is left as it was.
module OtelAsCode
  # A plain Ruby Logger (Sinatra, Rack, scripts): wraps the logger's own formatter so a line
  # written inside a span ends with " trace_id=... span_id=...". The format, level and output
  # stay the logger's; a JSON line is left untouched, since appended text would break it.
  def self.add_trace_ids(logger)
    inner = logger.formatter || ::Logger::Formatter.new
    logger.formatter = proc do |severity, time, progname, msg|
      line = inner.call(severity, time, progname, msg)
      ids = trace_log_tag
      next line if ids.nil? || line.lstrip.start_with?('{', '[')

      line.end_with?("\n") ? "#{line.chomp} #{ids}\n" : "#{line} #{ids}"
    end
    logger
  end

  # Rails: the tag config.log_tags asks for once per request; nil outside a span, which Rails drops.
  def self.trace_log_tag
    span = OpenTelemetry::Trace.current_span.context
    "trace_id=#{span.hex_trace_id} span_id=#{span.hex_span_id}" if span.valid?
  end
end
